        ungettext('%(value).1f decillion', '%(value).1f decillion', number),
        ungettext('%(value)s decillion', '%(value)s decillion', number),
    )),
    (100, lambda number: (
        ungettext('%(value).1f googol', '%(value).1f googol', number),
        ungettext('%(value)s googol', '%(value)s googol', number),
    )),
)

def intword(value):
    """
    Converts a large integer to a friendly text representation. Works best
    for numbers over 1 million. For example, 1000000 becomes '1.0 million',
    1200000 becomes '1.2 million' and '1200000000' becomes '1.2 billion'.
    """
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value

    if value < 1000000:
        return value

    def _check_for_i18n(value, float_formatted, string_formatted):
        """
        Use the i18n enabled defaultfilters.floatformat if possible
        """
        if settings.USE_L10N:
            value = defaultfilters.floatformat(value, 1)
            template = string_formatted
        else:
            template = float_formatted
        return template % {'value': value}

    for exponent, converters in intword_converters:
        large_number = 10 ** exponent
        if value < large_number * 1000:
            new_value = value / float(large_number)
            return _check_for_i18n(new_value, *converters(new_value))
    return value

def apnumber(value):
    """
    For numbers 1-9, returns the number spelled out. Otherwise, returns the
    number. This follows Associated Press style.
    """
    try:
        value = int(value)
    except (TypeError, ValueError):
        return value
    if not 0 < value < 10:
        return value
    return (_('one'), _('two'), _('three'), _('four'), _('five'), _('six'), _('seven'), _('eight'), _('nine'))[value-1]

def naturalday(value, arg=None):
    """
    For date values that are tomorrow, today or yesterday compared to
    present day returns representing string. Otherwise, returns a string
    formatted according to settings.DATE_FORMAT.
    """
    try:
        tzinfo = getattr(value, 'tzinfo', None)
        value = date(value.year, value.month, value.day)
    except AttributeError:
        # Passed value wasn't a date object
        return value
    except ValueError:
        # Date arguments out of range
        return value
    today = datetime.now(tzinfo).date()
    delta = value - today
    if delta.days == 0:
        return _('today')
    elif delta.days == 1:
        return _('tomorrow')
    elif delta.days == -1:
        return _('yesterday')
    return defaultfilters.date(value, arg)

def naturaltime(value):
    """
    For date and time values shows how many seconds, minutes or hours ago
    compared to current timestamp returns representing string.
    """
    if not isinstance(value, date): # datetime is a subclass of date
        return value

    now = datetime.now(utc if is_aware(value) else None)
    if value < now:
        delta = now - value
        if delta.days != 0:
            return pgettext(
                'naturaltime', '%(delta)s ago'
            ) % {'delta': defaultfilters.timesince(value, now)}
        elif delta.seconds == 0:
            return _('now')
        elif delta.seconds < 60:
            return ungettext(
                # Translators: please keep a non-breaking space (U+00A0)
                # between count and time unit.
                'a second ago', '%(count)s seconds ago', delta.seconds
            ) % {'count': delta.seconds}
        elif delta.seconds // 60 < 60:
            count = delta.seconds // 60
            return ungettext(
                # Translators: please keep a non-breaking space (U+00A0)
                # between count and time unit.
                'a minute ago', '%(count)s minutes ago', count
            ) % {'count': count}
        else:
            count = delta.seconds // 60 // 60
            return ungettext(
                # Translators: please keep a non-breaking space (U+00A0)
                # between count and time unit.
                'an hour ago', '%(count)s hours ago', count
            ) % {'count': count}
    else:
        delta = value - now
        if delta.days != 0:
            return pgettext(
                'naturaltime', '%(delta)s from now'
            ) % {'delta': defaultfilters.timeuntil(value, now)}
        elif delta.seconds == 0:
            return _('now')
        elif delta.seconds < 60:
            return ungettext(
                # Translators: please keep a non-breaking space (U+00A0)
                # between count and time unit.
                'a second from now', '%(count)s seconds from now', delta.seconds
            ) % {'count': delta.seconds}
        elif delta.seconds // 60 < 60:
            count = delta.seconds // 60
            return ungettext(
                # Translators: please keep a non-breaking space (U+00A0)
                # between count and time unit.
                'a minute from now', '%(count)s minutes from now', count
            ) % {'count': count}
        else:
            count = delta.seconds // 60 // 60
            return ungettext(
                # Translators: please keep a non-breaking space (U+00A0)
                # between count and time unit.
                'an hour from now', '%(count)s hours from now', count
            ) % {'count': count}

function resolveConfig(cmdArgs, configFile) {
	var config = {};
	if (configFile) {
		var configPath = path.dirname(configFile);
		config = require(configFile);
		Object.keys(config).forEach(function(key) {
			if (["input", "output", "features", "run"].indexOf(key) > -1) {
				config[key] = path.resolve(configPath, config[key]);
			}
		});
	}

	var finalConfig = {
		command : cmdArgs._[0] ? cmdArgs._[0].toLowerCase() : config.command,
		input : cmdArgs.input ? path.resolve(process.cwd(), cmdArgs.input) : config.input,
		output : cmdArgs.output ? path.resolve(process.cwd(), cmdArgs.output) : config.output,
		features : cmdArgs.features ? path.resolve(process.cwd(), cmdArgs.features) : config.features,
		variant : cmdArgs.variant ? cmdArgs.variant : config.variant,
		bin : cmdArgs.bin ? cmdArgs.bin : config.bin,
		launch : cmdArgs.launch ? cmdArgs.launch : config.launch,
		run : cmdArgs.run !== undefined 
			? cmdArgs.run != true ? cmdArgs.run : null
			: config.run,
		ext : [
			{ module : require("../extensions/report_core/extension.js") }
		]
	};

	if (cmdArgs.ext) {
		cmdArgs.ext.split(",").forEach(function(ext) {
			var extPath = ext;
			if (extPath.replace("\\","/").indexOf("/") > -1) { extPath = path.resolve(process.cwd(), ext); }
			finalConfig.ext.push({
				path : extPath
			});
		});
	} else if (config.ext) {
		config.ext.forEach(function(ext) {
			if (typeof(ext) == "string") {
				var extPath = ext;
				if (extPath.slice(0,1) == ".") { extPath = path.resolve(configPath, extPath); }
				finalConfig.ext.push({
					path : extPath
				});
			} else if (ext instanceof Function) {
				finalConfig.ext.push({
					module : ext
				});
			} else {
				var extPath = ext.path;
				if (extPath && extPath.slice(0,1) == ".") { extPath = path.resolve(configPath, extPath); }
				finalConfig.ext.push({
					options : ext.options,
					path : extPath ? extPath : null,
					module : ext.module ? ext.module : null
				});
			}
		});
	}

	return finalConfig;
}

function formatValue(value, fm, cc) {

    if (typeof value === 'function') {
        return formatValue(resolveFunc(value, cc), fm, cc);
    }

    const ctf = getCTF(value); // Custom Type Formatting
    if (ctf) {
        fm |= ctf.rawType ? fmFlags.raw : 0;
        return formatValue(resolveFunc(ctf.toPostgres, value), fm, cc);
    }

    const isRaw = !!(fm & fmFlags.raw);
    fm &= ~fmFlags.raw;

    switch (fm) {
        case fmFlags.alias:
            return $as.alias(value);
        case fmFlags.name:
            return $as.name(value);
        case fmFlags.json:
            return $as.json(value, isRaw);
        case fmFlags.csv:
            return $as.csv(value);
        case fmFlags.value:
            return $as.value(value);
        default:
            break;
    }

    if (isNull(value)) {
        throwIfRaw(isRaw);
        return 'null';
    }

    switch (typeof value) {
        case 'string':
            return $to.text(value, isRaw);
        case 'boolean':
            return $to.bool(value);
        case 'number':
            return $to.number(value);
        case 'symbol':
            throw new TypeError('Type Symbol has no meaning for PostgreSQL: ' + value.toString());
        default:
            if (value instanceof Date) {
                return $to.date(value, isRaw);
            }
            if (value instanceof Array) {
                return $to.array(value);
            }
            if (value instanceof Buffer) {
                return $to.buffer(value, isRaw);
            }
            return $to.json(value, isRaw);
    }
}

function genValuePartial_toObject(gen, field, fieldIndex, prop, map) {
  if (field.resolvedType) {
    if (field.resolvedType instanceof Enum) {
      if (map) {
        gen('d%s.set(k, o.enums===String?types[%i].values[m%s.get(k)]:m%s.get(k));', prop, fieldIndex, prop, prop);
      } else {
        gen('d%s=o.enums===String?types[%i].values[m%s]:m%s', prop, fieldIndex, prop, prop);
      }
    } else {
      if (map) {
        gen('d%s.set(k, types[%i].toObject(m%s.get(k),o));', prop, fieldIndex, prop);
      } else {
        gen('d%s=types[%i].toObject(m%s,o)', prop, fieldIndex, prop);
      }
    }
  } else {
    let isUnsigned = false;
    switch (field.type) {
      case 'double':
      case 'float':
        if (map) {
          gen('d%s.set(k, o.json&&!isFinite(m%s.get(k))?String(m%s.get(k)):m%s.get(k));', prop, prop, prop, prop);
        } else {
          gen('d%s=o.json&&!isFinite(m%s)?String(m%s):m%s;', prop, prop, prop, prop);
        }
        break;
      case 'uint64':
        isUnsigned = true;
        // eslint-disable-line no-fallthrough
      case 'int64':
      case 'sint64':
      case 'fixed64':
      case 'sfixed64':
        if (map) {
          gen('if(typeof m%s==="number"){', prop)('d%s.set(k, o.longs===String?String(m%s.get(k)):m%s.get(k));', prop, prop, prop)('} else {')('d%s.set(k, o.longs===String?util.Long.prototype.toString.call(m%s.get(k)):o.longs===Number?new util.LongBits(m%s.get(k).low>>>0,m%s.get(k).high>>>0).toNumber(%s):m%s.get(k));', prop, prop, prop, prop, isUnsigned ? 'true' : '', prop)('}');
        } else {
          gen('if(typeof m%s==="number"){', prop)('d%s=o.longs===String?String(m%s):m%s;', prop, prop, prop)('} else {')('d%s=o.longs===String?util.Long.prototype.toString.call(m%s):o.longs===Number?new util.LongBits(m%s.low>>>0,m%s.high>>>0).toNumber(%s):m%s', prop, prop, prop, prop, isUnsigned ? 'true' : '', prop)('}');
        }
        break;
      case 'bytes':
        if (map) {
          gen('d%s.set(k, o.bytes===String?util.base64.encode(m%s.get(k),0,m%s.get(k).length):o.bytes===Array?Array.prototype.slice.call(m%s.get(k)):m%s.get(k));', prop, prop, prop, prop, prop);
        } else {
          gen('d%s=o.bytes===String?util.base64.encode(m%s,0,m%s.length):o.bytes===Array?Array.prototype.slice.call(m%s):m%s', prop, prop, prop, prop, prop);
        }
        break;
      default:
        if (map) {
          gen('d%s.set(k, m%s.get(k));', prop, prop);
        } else {
          gen('d%s=m%s', prop, prop);
        }
        break;
    }
  }
  return gen;
}

function genValuePartial_fromObject(gen, field, fieldIndex, prop) {
  if (field.resolvedType) {
    if (field.resolvedType instanceof Enum) {
      gen('switch(d%s){', prop);
      for (let values = field.resolvedType.values, keys = Object.keys(values), i = 0; i < keys.length; ++i) {
        if (field.repeated && values[keys[i]] === field.typeDefault) gen('default:');
        gen('case%j:', keys[i])('case %i:', values[keys[i]])('m%s=%j', prop, values[keys[i]])('break');
      }
      gen('}');
    } else {
      gen('if(typeof d%s!=="object")', prop)('throw TypeError(%j)', field.fullName + ': object expected')('m%s=types[%i].fromObject(d%s)', prop, fieldIndex, prop);
    }
  } else {
    let isUnsigned = false;
    switch (field.type) {
      case 'double':
      case 'float':
        gen('m%s=Number(d%s)', prop, prop); // also catches "NaN", "Infinity"
        break;
      case 'uint32':
      case 'fixed32':
        gen('m%s=d%s>>>0', prop, prop);
        break;
      case 'int32':
      case 'sint32':
      case 'sfixed32':
        gen('m%s=d%s|0', prop, prop);
        break;
      case 'uint64':
        isUnsigned = true;
        // eslint-disable-line no-fallthrough
      case 'int64':
      case 'sint64':
      case 'fixed64':
      case 'sfixed64':
        gen('if(util.Long)')('(m%s=util.Long.fromValue(d%s)).unsigned=%j', prop, prop, isUnsigned)('else if(typeof d%s==="string")', prop)('m%s=parseInt(d%s,10)', prop, prop)('else if(typeof d%s==="number")', prop)('m%s=d%s', prop, prop)('else if(typeof d%s==="object")', prop)('m%s=new util.LongBits(d%s.low>>>0,d%s.high>>>0).toNumber(%s)', prop, prop, prop, isUnsigned ? 'true' : '');
        break;
      case 'bytes':
        gen('if(typeof d%s==="string")', prop)('util.base64.decode(d%s,m%s=util.newBuffer(util.base64.length(d%s)),0)', prop, prop, prop)('else if(d%s.length)', prop)('m%s=d%s', prop, prop);
        break;
      case 'string':
        gen('m%s=String(d%s)', prop, prop);
        break;
      case 'bool':
        gen('m%s=Boolean(d%s)', prop, prop);
        break;
      default:
        break;
        /* default: gen
            ("m%s=d%s", prop, prop);
            break; */
    }
  }
  return gen;
}

function DeviceFirmwareBundle() {
    var firmwareImageInformation = null;
    var firmwareImage = null;
    var deviceImage = null;
    var device = null;
    var curatedDevice = null;

    var initialDeviceState = {};

    var version = null;
    var serial = null;
    var connectionType = null;
    var deviceType = null;
    var deviceTypeString = null;

    var progressListener = null;

    this.setProgressListener = function(newListener) {
        progressListener = newListener;
    };
    this.getProgressListener = function() {
        return progressListener;
    };
    this.updateProgressScaled = function(value) {
        if (shouldUpdateProgressBar) {
            var scaledValue = curScaling * value + curOffset;
            progressListener.updatePercentage(scaledValue, nop);
            // console.log('Updating progress...', serial, scaledValue);
        }
    };
    /**
     * Get the raw contents of the firmware image.
     *
     * Get the contents of the firmware that the device is being upgraded to.
     * This is the raw file contents (binary) as read from the firmware bin
     * file.
     *
     * @return {Buffer} A node standard library Buffer with the raw firmware
     *      file contents.
    **/
    this.getFirmwareImage = function() {
        return firmwareImage;
    };

    /** 
     * Specify the raw contents of the firmware image.
     *
     * Provide the firmware that the device should be upgraded to. This is the
     * raw contents (binary) that will be written as the firmware image to the
     * device.
     *
     * @param {Buffer} newFirmwareImage A node standard library Buffer with the
     *      raw firmware (file) contents.
    **/
    this.setFirmwareImage = function(newFirmwareImage) {
        firmwareImage = newFirmwareImage;
    };

    /**
     * Get the image information header.
     *
     * Get the image information header for the firmware image that is being
     * written to the device.
     *
     * @return {Object} Object with information about the image being written
     *      to the device.
    **/
    this.getFirmwareImageInformation = function() {
        return firmwareImageInformation;
    };

    function getUpgradeTargetFlashInfo() {
        var upgradeTarget = firmwareImageInformation.intendedDevice;
        var upgradeTargetStr = upgradeTarget.toString();
        var info = UPGRADE_TARGET_FLASH_INFO[upgradeTargetStr];
        // console.log('Returning Flash Info', info);
        if(false) {
            var keys = Object.keys(info);
            keys.forEach(function(key) {
                var  numStr = info[key].toString(16).toUpperCase();
                console.log('Flash Info: ' + key, '0x' + numStr);
            });
        }
        if(info) {
            return info;
        } else {
            return DEFAULT_UPGRADE_TARGET_FLASH_INFO;
        }
    }
    this.getUpgradeTargetFlashInfo = getUpgradeTargetFlashInfo;

    function isLoadingRecoveryFW() {
        var info = getUpgradeTargetFlashInfo();
        return info.isRecoveryFW;
    }
    this.isLoadingRecoveryFW = isLoadingRecoveryFW;

    this.setConnectionType = function(newConnectionType) {
        connectionType = newConnectionType;
    };
    this.setDeviceType = function(newDeviceType) {
        var dtInt = driver_const.deviceTypes[newDeviceType];
        deviceType = dtInt;
        deviceTypeString = driver_const.DRIVER_DEVICE_TYPE_NAMES[dtInt];
    };

    /**
     * Provide information about the image that is being written.
     *
     * Provide information parsed from the image header about that image.
     * Should include a rawImageInfo attribute that has the Node standard lib
     * Buffer with the raw data read from the bin file.
     *
     * @param {Object} newFirmwareImageInformation Object with parsed firmware
     *      image information.
    **/
    this.setFirmwareImageInformation = function(newFirmwareImageInformation) {
        firmwareImageInformation = newFirmwareImageInformation;
    };

    /**
     * Set the labjack-nodejs device object to operate on.
     *
     * Provide the labjack-nodejs device object that corresponds / encapsulates
     * the device to upgrade.
     *
     * @param {labjack-nodejs.device} newDevice The device to upgrade.
    **/
    this.setDevice = function(newDevice) {
        device = newDevice;
    };

    /**
     * Set the curated device object that is being operated on.
    **/
    this.setCuratedDevice = function(newCuratedDevice) {
        curatedDevice = newCuratedDevice;
    };

    /**
     * Get the device that should be upgraded.
     *
     * Get the labjack-nodejs device that encapsulates the LabJack that should
     * be upgraded.
     *
    **/
    this.getDevice = function() {
        return device;
    };

    /**
     * Get the curated device being upgraded
    **/
    this.getCuratedDevice = function() {
        return curatedDevice;
    };

    /**
     * Get the version of the firmware that is being installed on the device.
     *
     * @return {float} The version of the firmware that is being written to the
     *      device as part of this upgrade.
    **/
    this.getFirmwareVersion = function() {
        return version;
    };

    /**
     * Set the version of the firmware that is being installed on the device.
     *
     * @param {float} The version of the firmware that is being written to the
     *      device as part of this upgrade.
    **/
    this.setFirmwareVersion = function(newVersion) {
        version = newVersion;
    };

