function setParameters(params) {
    var modal = getModal();

    var $title = modal.querySelector('h2'),
        $text = modal.querySelector('p'),
        $cancelBtn = modal.querySelector('button.cancel'),
        $confirmBtn = modal.querySelector('button.confirm');

    // Title
    $title.innerHTML = escapeHtml(params.title).split("\n").join("<br>");

    // Text
    $text.innerHTML = escapeHtml(params.text || '').split("\n").join("<br>");
    if (params.text) {
      show($text);
    }

    //Custom Class
    if (params.customClass) {
      addClass(modal, params.customClass);
    }

    // Icon
    hide(modal.querySelectorAll('.icon'));
    if (params.type) {
      var validType = false;
      for (var i = 0; i < alertTypes.length; i++) {
        if (params.type === alertTypes[i]) {
          validType = true;
          break;
        }
      }
      if (!validType) {
        window.console.error('Unknown alert type: ' + params.type);
        return false;
      }
      var $icon = modal.querySelector('.icon.' + params.type);
      show($icon);

      // Animate icon
      switch (params.type) {
        case "success":
          addClass($icon, 'animate');
          addClass($icon.querySelector('.tip'), 'animateSuccessTip');
          addClass($icon.querySelector('.long'), 'animateSuccessLong');
          break;
        case "error":
          addClass($icon, 'animateErrorIcon');
          addClass($icon.querySelector('.x-mark'), 'animateXMark');
          break;
        case "warning":
          addClass($icon, 'pulseWarning');
          addClass($icon.querySelector('.body'), 'pulseWarningIns');
          addClass($icon.querySelector('.dot'), 'pulseWarningIns');
          break;
      }

    }

    // Custom image
    if (params.imageUrl) {
      var $customIcon = modal.querySelector('.icon.custom');

      $customIcon.style.backgroundImage = 'url(' + params.imageUrl + ')';
      show($customIcon);

      var _imgWidth  = 80,
          _imgHeight = 80;

      if (params.imageSize) {
        var imgWidth  = params.imageSize.split('x')[0];
        var imgHeight = params.imageSize.split('x')[1];

        if (!imgWidth || !imgHeight) {
          window.console.error("Parameter imageSize expects value with format WIDTHxHEIGHT, got " + params.imageSize);
        } else {
          _imgWidth  = imgWidth;
          _imgHeight = imgHeight;

          $customIcon.css({
            'width': imgWidth + 'px',
            'height': imgHeight + 'px'
          });
        }
      }
      $customIcon.setAttribute('style', $customIcon.getAttribute('style') + 'width:' + _imgWidth + 'px; height:' + _imgHeight + 'px');
    }

    // Cancel button
    modal.setAttribute('data-has-cancel-button', params.showCancelButton);
    if (params.showCancelButton) {
      $cancelBtn.style.display = 'inline-block';
    } else {
      hide($cancelBtn);
    }

    // Edit text on cancel and confirm buttons
    if (params.cancelButtonText) {
      $cancelBtn.innerHTML = escapeHtml(params.cancelButtonText);
    }
    if (params.confirmButtonText) {
      $confirmBtn.innerHTML = escapeHtml(params.confirmButtonText);
    }

    // Set confirm button to selected background color
    $confirmBtn.style.backgroundColor = params.confirmButtonColor;

    // Set box-shadow to default focused button
    setFocusStyle($confirmBtn, params.confirmButtonColor);

    // Allow outside click?
    modal.setAttribute('data-allow-ouside-click', params.allowOutsideClick);

    // Done-function
    var hasDoneFunction = (params.doneFunction) ? true : false;
    modal.setAttribute('data-has-done-function', hasDoneFunction);

    // Close timer
    modal.setAttribute('data-timer', params.timer);
  }

def create_app_from_yml(path):
    """Return an application instance created from YAML."""

    try:
        with open(path, "rt", encoding="UTF-8") as f:
            try:
                # Substitute ALL occurrences of '%(here)s' with a path to a
                # directory with '.holocron.yml'. Please note, we also want
                # wrap the result into 'io.StringIO' in order to preserve
                # original filename in 'yaml.safe_load()' errors.
                interpolated = io.StringIO(f.read() % {
                    "here": os.path.abspath(os.path.dirname(path))})
                interpolated.name = f.name

                conf = yaml.safe_load(interpolated)
            except yaml.YAMLError as exc:
                raise RuntimeError(
                    "Cannot parse a configuration file. Context: " + str(exc))

    except FileNotFoundError:
        conf = {"metadata": None, "pipes": {}}

    return core.create_app(conf["metadata"], pipes=conf["pipes"])

function Endpoint(fnWrite, key, port, hostname, opts) {
    assert(_.isFunction(fnWrite));
    assert(_.isString(key));

    _.extend(this, EventEmitter);
    _.bindAll(this, _.functionsIn(this));
    opts = opts || {};

    if (!fnWrite || typeof fnWrite !== 'function') {
      throw new Error("Endpoint `fnWrite` parameter is not defined or is not a function");
    }

    if (!key) {
      throw new Error("Endpoint `key` parameter is not defined");
    }

    if (!port) {
      throw new Error("connect(port, hostname) port must be defined");
    }
    if (!hostname) {
      throw new Error("connect(port, hostname) hostname must be defined");
    }

    this.key = key;

    /**
     * redsmin ssl connection server hostname
     * @type {String}
     */
    this.hostname = hostname;

    /**
     * redsmin ssl connection server hostname
     * @type {String}
     */
    this.port = port;

    /**
     * redsmin ssl connection server hostname
     * @type {String}
     */
    this.uri = this.hostname + ':' + this.port;

    this.auth = opts.auth;
    this.handshaken = false;
    this.connected = false;
    this.connecting = false;
    this.socket = null;
    this.fnWrite = fnWrite;

    this.handshakenBackoff = backoff.fibonacci({
      initialDelay: opts.initialTimeout || 500,
      maxDelay: opts.maxTimeout || 10000
    });

    this.handshakenBackoff.on('backoff', this.reconnect);

    this.reconnectBackoff = backOff(this.reconnect, {
      min: 500,
      max: 4000,
      inc: 250
    });
  }

function () {

    function getRider() {
      if (process.env.LIGHTSQLSERVER_HOST) {
        return sqlserverRider;
      }
      if (process.env.LIGHTMYSQL_HOST) {
        return mysqlRider;
      }
      return mongoRider;
    }

    // 遍历所有board，以class名注册类，并添加board方法
    this.board.forEach(item => {
      this[item.class] = this[item.class] || {};

      log.debug(`>>>> ${item.api} ${item.class} ${item.action} ${CONST.METHOD[item.type]}`);

      this[item.class][item.action] = (handler, params, callback) => {

        // params参数未指定
        if (typeof params === 'function') {
          callback = params;
          params = undefined;
        }

        // 添加参数
        handler = handler.copy(params || handler.params);
        handler.api = item;

        const func = getRider()[CONST.BOARD_TYPE[item.type]];
        if (func) {
          return func.call(this, handler, callback);
        }

        log.debug('no method. ' + item.class + '#' + item.action);
        callback(new error.class.MethodNotFoundError());
      };
    });
  }

    def build_text(self):
