async function mergeRenovateConfig(config) {
  let returnConfig = { ...config };
  const fileList = await platform.getFileList();
  async function detectConfigFile() {
    for (const fileName of configFileNames) {
      if (fileName === 'package.json') {
        try {
          const pJson = JSON.parse(await platform.getFile('package.json'));
          if (pJson.renovate) {
            logger.info('Using package.json for global renovate config');
            return 'package.json';
          }
        } catch (err) {
          // Do nothing
        }
      } else if (fileList.includes(fileName)) {
        return fileName;
      }
    }
    return null;
  }
  const configFile = await detectConfigFile();
  if (!configFile) {
    logger.debug('No renovate config file found');
    return returnConfig;
  }
  logger.debug(`Found ${configFile} config file`);
  let renovateJson;
  if (configFile === 'package.json') {
    // We already know it parses
    renovateJson = JSON.parse(await platform.getFile('package.json')).renovate;
    logger.info({ config: renovateJson }, 'package.json>renovate config');
  } else {
    let renovateConfig = await platform.getFile(configFile);
    // istanbul ignore if
    if (renovateConfig === null) {
      logger.warn('Fetching renovate config returns null');
      throw new Error('registry-failure');
    }
    // istanbul ignore if
    if (!renovateConfig.length) {
      renovateConfig = '{}';
    }

    const fileType = path.extname(configFile);

    if (fileType === '.json5') {
      try {
        renovateJson = JSON5.parse(renovateConfig);
      } catch (err) /* istanbul ignore next */ {
        logger.debug(
          { renovateConfig },
          'Error parsing renovate config renovate.json5'
        );
        const error = new Error('config-validation');
        error.configFile = configFile;
        error.validationError = 'Invalid JSON5 (parsing failed)';
        error.validationMessage = 'JSON5.parse error: ' + err.message;
        throw error;
      }
    } else {
      let allowDuplicateKeys = true;
      let jsonValidationError = jsonValidator.validate(
        renovateConfig,
        allowDuplicateKeys
      );
      if (jsonValidationError) {
        const error = new Error('config-validation');
        error.configFile = configFile;
        error.validationError = 'Invalid JSON (parsing failed)';
        error.validationMessage = jsonValidationError;
        throw error;
      }
      allowDuplicateKeys = false;
      jsonValidationError = jsonValidator.validate(
        renovateConfig,
        allowDuplicateKeys
      );
      if (jsonValidationError) {
        const error = new Error('config-validation');
        error.configFile = configFile;
        error.validationError = 'Duplicate keys in JSON';
        error.validationMessage = JSON.stringify(jsonValidationError);
        throw error;
      }
      try {
        renovateJson = JSON.parse(renovateConfig);
      } catch (err) /* istanbul ignore next */ {
        logger.debug({ renovateConfig }, 'Error parsing renovate config');
        const error = new Error('config-validation');
        error.configFile = configFile;
        error.validationError = 'Invalid JSON (parsing failed)';
        error.validationMessage = 'JSON.parse error: ' + err.message;
        throw error;
      }
    }
    logger.info({ configFile, config: renovateJson }, 'Repository config');
  }
  const migratedConfig = await migrateAndValidate(config, renovateJson);
  if (migratedConfig.errors.length) {
    const error = new Error('config-validation');
    error.configFile = configFile;
    error.validationError =
      'The renovate configuration file contains some invalid settings';
    error.validationMessage = migratedConfig.errors
      .map(e => e.message)
      .join(', ');
    throw error;
  }
  if (migratedConfig.warnings) {
    returnConfig.warnings = returnConfig.warnings.concat(
      migratedConfig.warnings
    );
  }
  delete migratedConfig.errors;
  delete migratedConfig.warnings;
  logger.debug({ config: migratedConfig }, 'migrated config');
  // Decrypt before resolving in case we need npm authentication for any presets
  const decryptedConfig = decryptConfig(migratedConfig, config.privateKey);
  // istanbul ignore if
  if (decryptedConfig.npmrc) {
    logger.debug('Found npmrc in decrypted config - setting');
    npmApi.setNpmrc(decryptedConfig.npmrc);
  }
  // Decrypt after resolving in case the preset contains npm authentication instead
  const resolvedConfig = decryptConfig(
    await presets.resolveConfigPresets(decryptedConfig),
    config.privateKey
  );
  delete resolvedConfig.privateKey;
  logger.trace({ config: resolvedConfig }, 'resolved config');
  // istanbul ignore if
  if (resolvedConfig.npmrc) {
    logger.debug(
      'Ignoring any .npmrc files in repository due to configured npmrc'
    );
    npmApi.setNpmrc(resolvedConfig.npmrc);
    resolvedConfig.ignoreNpmrcFile = true;
  }
  // istanbul ignore if
  if (resolvedConfig.hostRules) {
    logger.info('Setting hostRules from config');
    resolvedConfig.hostRules.forEach(hostRules.update);
    delete resolvedConfig.hostRules;
  }
  returnConfig = mergeChildConfig(returnConfig, resolvedConfig);
  returnConfig.renovateJsonPresent = true;
  returnConfig.packageRules = flattenPackageRules(returnConfig.packageRules);
  // istanbul ignore if
  if (returnConfig.ignorePaths && returnConfig.ignorePaths.length) {
    logger.debug(
      { ignorePaths: returnConfig.ignorePaths },
      `Found repo ignorePaths`
    );
  }
  return returnConfig;
}

function Routing() {

    var self        = {};

    /**
     * @function getRoute
     *
     * @param {string} rule e.g.: <name>[@<bundle>]
     * @param {object} params
     *
     * @return {object} route
     * */
    self.getRoute = function(rule, params) {

        var config      = getContext('gina').config
            , bundle    = null;

        if ( /\@/.test(rule) ) {
            bundle = rule.split(/\@/)[1];
        } else {
            bundle    = config.bundle
        }

        var env     = config.env
        , routing   = config.getRouting(bundle, env);

        if ( typeof(routing[rule]) == 'undefined' ) {
            throw new Error('[ RoutingHelper::getRouting(rule, params) ] : `' +rule + '` not found !')
        }

        var route = JSON.parse(JSON.stringify(routing[rule]));
        var variable = null
        for (var p in route.param) {
            if ( /^:/.test(route.param[p]) ) {
                variable = route.param[p].substr(1);
                if ( typeof(params[variable]) != 'undefined') {
                    route.url = route.url.replace( new RegExp('(/:'+variable+'|/:'+variable+'$)', 'g'), '/'+ params[variable] );

                    if ( typeof(route.param.path) != 'undefined' && /:/.test(route.param.path) ) {
                        route.param.path = route.param.path.replace( new RegExp('(:'+variable+'/|:'+variable+'$)', 'g'), params[variable]);
                    }
                }
            }
        }

        if ( Array.isArray(route.url) ) {
            route.url = route.url[0]
        }

        return route

    };

    /**
     * Get route by url
     * N.B.: this will only work with rules declared with `GET` method property
     *
     * @function getRouteByUrl
     *
     * @param {string} url e.g.: /bundle/some/url/path or http
     * @param {string} [bundle] targeted bundle
     *
     * @return {object} route
     * */
    self.getRouteByUrl = function (url, bundle) {

        var matched         = false
            , pathname      = null
            , gnaCtx        = getContext('gina')
            , config        = gnaCtx.config
            , bundle        = ( typeof(bundle) != 'undefined' ) ? bundle : config.bundle
            , env           = config.env
            , router        = new gnaCtx.Router(env)
            , routing       = config.getRouting(bundle, env)
            , isRoute       = null
            , route         = null
            , isXMLRequest  = getContext().router.isProcessingXMLRequest
        ;

        var hostname    = config.envConf[bundle][env].hostname
            , uri       = config.envConf[bundle][env].server.webroot
            , prefix    = hostname + uri;

        pathname = url.replace( new RegExp('^'+ hostname), '');

        var request = {
            routing: {
                path: unescape(pathname)
            },
            method: 'GET',
            params: {}

        };

        out:
            for (var rule in routing) {
                if (typeof(routing[rule]['param']) == 'undefined')
                    break;

                if (routing[rule].bundle != bundle) continue;

                // this will only work with rules declared with `GET` method property
                if ( typeof(routing[rule].method) != 'undefined' && !/^get$/i.test(routing[rule].method) ) continue;

                //Preparing params to relay to the router.
                params = {
                    method              : routing[rule].method || 'GET',
                    requirements        : routing[rule].requirements,
                    namespace           : routing[rule].namespace || undefined,
                    url                 : unescape(pathname), /// avoid %20
                    rule                : routing[rule].originalRule || rule,
                    param               : routing[rule].param,
                    middleware          : routing[rule].middleware,
                    bundle              : routing[rule].bundle,
                    isXMLRequest        : isXMLRequest
                };

                //Parsing for the right url.
                try {
                    isRoute = router.compareUrls(request, params, routing[rule].url);
                } catch (err) {
                    throw new Error('Rule [ '+rule+' ] needs your attention.\n' + err.stack);
                    break;
                }

                if (isRoute.past) {

                    route = JSON.parse(JSON.stringify(routing[rule]));

                    matched = true;
                    isRoute = {};
                    break out;

                }
            }

        if (!matched) {
            throw new Error('[ RoutingHelper::getRouteByUrl(rule[, bundle]) ] : route not found for url: `' + url + '` !')
        } else {
            return route
        }

    }

    return self
}

function (name, value, type) {
    //数据类型存在则检查
    if (type) {
        //字段类型严格验证
        switch (type) {
            case 'integer':
            case 'float':
                if (!lib.isNumber(value)) {
                    return { status: 0, msg: `${name}值类型错误!` };
                }
                break;
            case 'json':
                if (!lib.isJSONObj(value)) {
                    return { status: 0, msg: `${name}值类型错误!` };
                }
                break;
            case 'array':
                if (!lib.isArray(value)) {
                    return { status: 0, msg: `${name}值类型错误!` };
                }
                break;
            case 'string':
            case 'text':
                if (!lib.isString(value)) {
                    return { status: 0, msg: `${name}值类型错误!` };
                }
                break;
            default:
                if (!lib.isString(value)) {
                    return { status: 0, msg: `${name}值类型错误!` };
                }
                break;
        }
    }

    return { status: 1, msg: '' };
}

function (name, value, extra, method) {
    let result = { status: 1, msg: '' };
    if (!name) {
        return result;
    }
    //自定义规则存在则检查
    if (extra && extra.valid) {
        let met;
        if (extra.method) {
            met = (extra.method).toUpperCase();
            if (met === 'ALL' || met === method) {
                met = true;
            } else {
                met = false;
            }
        }
        if (met) {
            let valid = extra.valid;
            if (!Array.isArray(valid)) {
                valid = [valid];
            }
            valid.some(function (validItem) {
                //自定义检测方法
                if (typeof validItem === 'function') {
                    result = validItem(value);
                } else if (typeof (rules[validItem]) === 'function') {
                    let args = extra[validItem + '_args'] || [];
                    if (!Array.isArray(args)) {
                        args = [args];
                    }
                    args = [value].concat(args);
                    if (rules[validItem].apply(rules, args) === false) {
                        result = { status: 0, msg: `${extra.msg[validItem]}` || `${name}值未通过检测!` };
                    }
                }
            });
        }
    }
    return result;
}

def load_messages(self, directory, catalogue):
        """
        Loads translation found in a directory.

        @type directory: string
        @param directory: The directory to search

        @type catalogue: MessageCatalogue
        @param catalogue: The message catalogue to dump

        @raises: ValueError
        """
        if not os.path.isdir(directory):
            raise ValueError("{0} is not a directory".format(directory))

        for format, loader in list(self.loaders.items()):
            extension = "{0}.{1}".format(catalogue.locale, format)
            files = find_files(directory, "*.{0}".format(extension))
            for file in files:
                domain = file.split("/")[-1][:-1 * len(extension) - 1]
                catalogue.add_catalogue(
                    loader.load(
                        file,
                        catalogue.locale,
                        domain))

function QueryFile(file, options) {

    if (!(this instanceof QueryFile)) {
        return new QueryFile(file, options);
    }

    let sql, error, ready, modTime, filePath = file;

    const opt = npm.assertOptions(options, {
        debug: npm.utils.isDev(),
        minify: (options && options.compress && options.minify === undefined) ? true : undefined,
        compress: undefined,
        params: undefined,
        noWarnings: undefined
    });

    Object.freeze(opt);

    if (npm.utils.isText(filePath) && !npm.utils.isPathAbsolute(filePath)) {
        filePath = npm.path.join(npm.utils.startDir, filePath);
    }

    // istanbul ignore next:
    if (!opt.noWarnings) {
        if (filePath in usedPath) {
            usedPath[filePath]++;
            npm.con.warn('WARNING: Creating a duplicate QueryFile object for the same file - \n    %s\n%s\n', filePath, npm.utils.getLocalStack(3));
        } else {
            usedPath[filePath] = 0;
        }
    }

    this[npm.formatting.as.ctf.rawType] = true; // do not format the content when used as a formatting value

    /**
     * @method QueryFile#prepare
     * @summary Prepares the query for execution.
     * @description
     * If the query hasn't been prepared yet, it will read the file and process the content according
     * to the parameters passed into the constructor.
     *
     * This method is primarily for internal use by the library.
     *
     * @param {boolean} [throwErrors=false]
     * Throw any error encountered.
     *
     */
    this.prepare = function (throwErrors) {
        let lastMod;
        if (opt.debug && ready) {
            try {
                lastMod = npm.fs.statSync(filePath).mtime.getTime();
                if (lastMod === modTime) {
                    // istanbul ignore next;
                    // coverage for this works differently under Windows and Linux
                    return;
                }
                ready = false;
            } catch (e) {
                sql = undefined;
                ready = false;
                error = e;
                if (throwErrors) {
                    throw error;
                }
                return;
            }
        }
        if (ready) {
            return;
        }
        try {
            sql = npm.fs.readFileSync(filePath, 'utf8');
            modTime = lastMod || npm.fs.statSync(filePath).mtime.getTime();
            if (opt.minify && opt.minify !== 'after') {
                sql = npm.minify(sql, {compress: opt.compress});
            }
            if (opt.params !== undefined) {
                sql = npm.formatting.as.format(sql, opt.params, {partial: true});
            }
            if (opt.minify && opt.minify === 'after') {
                sql = npm.minify(sql, {compress: opt.compress});
            }
            ready = true;
            error = undefined;
        } catch (e) {
            sql = undefined;
            error = new npm.QueryFileError(e, this);
            if (throwErrors) {
                throw error;
            }
        }
    };

    /**
     * @name QueryFile#Symbol(QueryFile.$query)
     * @type {string}
     * @default undefined
     * @readonly
     * @private
     * @summary Prepared query string.
     * @description
     * When property {@link QueryFile#error error} is set, the query is `undefined`.
     *
     * **IMPORTANT:** This property is for internal use by the library only, never use this
     * property directly from your code.
     */
    Object.defineProperty(this, QueryFile.$query, {
        get() {
            return sql;
        }
    });

    /**
     * @name QueryFile#error
     * @type {errors.QueryFileError}
     * @default undefined
     * @readonly
     * @description
     * When in an error state, it is set to a {@link errors.QueryFileError QueryFileError} object. Otherwise, it is `undefined`.
     */
    Object.defineProperty(this, 'error', {
        get() {
            return error;
        }
    });

    /**
     * @name QueryFile#file
     * @type {string}
     * @readonly
     * @description
     * File name that was passed into the constructor.
     *
     * This property is primarily for internal use by the library.
     */
    Object.defineProperty(this, 'file', {
        get() {
            return file;
        }
    });

    /**
     * @name QueryFile#options
     * @type {QueryFile.Options}
     * @readonly
     * @description
     * Set of options, as configured during the object's construction.
     *
     * This property is primarily for internal use by the library.
     */
    Object.defineProperty(this, 'options', {
        get() {
            return opt;
        }
    });

    this.prepare();
}

function expandContentElements(nodes, includeTextNodes) {
  const expanded = Array.prototype.map.call(nodes, node => {
    // We want to see if the node is an instanceof HTMLSlotELement, but
    // that class won't exist if the browser that doesn't support native
    // Shadow DOM and if the Shadow DOM polyfill hasn't been loaded. Instead,
    // we do a simplistic check to see if the tag name is "slot".
    const isSlot = typeof HTMLSlotElement !== 'undefined' ?
      node instanceof HTMLSlotElement :
      node.localName === 'slot';
    if (isSlot) {
      // Use the nodes assigned to this node instead.
      const assignedNodes = node.assignedNodes({ flatten: true });
      return assignedNodes ?
        expandContentElements(assignedNodes, includeTextNodes) :
        [];
    } else if (node instanceof HTMLElement) {
      // Plain element; use as is.
      return [node];
    } else if (node instanceof Text && includeTextNodes) {
      // Text node.
      return [node];
    } else {
      // Comment, processing instruction, etc.; skip.
      return [];
    }
  });
  const flattened = [].concat(...expanded);
  return flattened;
}

import stringprep, re, codecs

from unicodedata import ucd_3_2_0 as unicodedata

dots = re.compile("[\u002E\u3002\uFF0E\uFF61]")

ace_prefix = b"xn--"

sace_prefix = "xn--"

def nameprep(label):
    # Map
    newlabel = []
    for c in label:
        if stringprep.in_table_b1(c):
            # Map to nothing
            continue
        newlabel.append(stringprep.map_table_b2(c))
    label = "".join(newlabel)

    # Normalize
    label = unicodedata.normalize("NFKC", label)

    # Prohibit
    for c in label:
        if stringprep.in_table_c12(c) or \
           stringprep.in_table_c22(c) or \
           stringprep.in_table_c3(c) or \
           stringprep.in_table_c4(c) or \
           stringprep.in_table_c5(c) or \
           stringprep.in_table_c6(c) or \
           stringprep.in_table_c7(c) or \
           stringprep.in_table_c8(c) or \
           stringprep.in_table_c9(c):
            raise UnicodeError("Invalid character %r" % c)

    # Check bidi
    RandAL = [stringprep.in_table_d1(x) for x in label]
    for c in RandAL:
        if c:
            # There is a RandAL char in the string. Must perform further
            # tests:
            # 1) The characters in section 5.8 MUST be prohibited.
            # This is table C.8, which was already checked
            # 2) If a string contains any RandALCat character, the string
            # MUST NOT contain any LCat character.
            if any(stringprep.in_table_d2(x) for x in label):
                raise UnicodeError("Violation of BIDI requirement 2")

            # 3) If a string contains any RandALCat character, a
            # RandALCat character MUST be the first character of the
            # string, and a RandALCat character MUST be the last
            # character of the string.
            if not RandAL[0] or not RandAL[-1]:
                raise UnicodeError("Violation of BIDI requirement 3")

    return label

def ToASCII(label):
    try:
        # Step 1: try ASCII
        label = label.encode("ascii")
    except UnicodeError:
        pass
    else:
        # Skip to step 3: UseSTD3ASCIIRules is false, so
        # Skip to step 8.
        if 0 < len(label) < 64:
            return label
        raise UnicodeError("label empty or too long")

    # Step 2: nameprep
    label = nameprep(label)

    # Step 3: UseSTD3ASCIIRules is false
    # Step 4: try ASCII
    try:
        label = label.encode("ascii")
    except UnicodeError:
        pass
    else:
        # Skip to step 8.
        if 0 < len(label) < 64:
            return label
        raise UnicodeError("label empty or too long")

    # Step 5: Check ACE prefix
    if label.startswith(sace_prefix):
        raise UnicodeError("Label starts with ACE prefix")

    # Step 6: Encode with PUNYCODE
    label = label.encode("punycode")

    # Step 7: Prepend ACE prefix
    label = ace_prefix + label

    # Step 8: Check size
    if 0 < len(label) < 64:
        return label
    raise UnicodeError("label empty or too long")

def ToUnicode(label):
    # Step 1: Check for ASCII
    if isinstance(label, bytes):
        pure_ascii = True
    else:
        try:
            label = label.encode("ascii")
            pure_ascii = True
        except UnicodeError:
            pure_ascii = False
    if not pure_ascii:
        # Step 2: Perform nameprep
        label = nameprep(label)
        # It doesn't say this, but apparently, it should be ASCII now
        try:
            label = label.encode("ascii")
        except UnicodeError:
            raise UnicodeError("Invalid character in IDN label")
    # Step 3: Check for ACE prefix
    if not label.startswith(ace_prefix):
        return str(label, "ascii")

    # Step 4: Remove ACE prefix
    label1 = label[len(ace_prefix):]

    # Step 5: Decode using PUNYCODE
    result = label1.decode("punycode")

    # Step 6: Apply ToASCII
    label2 = ToASCII(result)

    # Step 7: Compare the result of step 6 with the one of step 3
    # label2 will already be in lower case.
    if str(label, "ascii").lower() != str(label2, "ascii"):
        raise UnicodeError("IDNA does not round-trip", label, label2)

    # Step 8: return the result of step 5
    return result

class Codec(codecs.Codec):
    def encode(self, input, errors='strict'):

        if errors != 'strict':
            # IDNA is quite clear that implementations must be strict
            raise UnicodeError("unsupported error handling "+errors)

        if not input:
            return b'', 0

        result = bytearray()
        labels = dots.split(input)
        if labels and not labels[-1]:
            trailing_dot = b'.'
            del labels[-1]
        else:
            trailing_dot = b''
        for label in labels:
            if result:
                # Join with U+002E
                result.extend(b'.')
            result.extend(ToASCII(label))
        return bytes(result+trailing_dot), len(input)

    def decode(self, input, errors='strict'):

        if errors != 'strict':
            raise UnicodeError("Unsupported error handling "+errors)

        if not input:
            return "", 0

        # IDNA allows decoding to operate on Unicode strings, too.
        if not isinstance(input, bytes):
            # XXX obviously wrong, see #3232
            input = bytes(input)
        labels = input.split(b".")

        if labels and len(labels[-1]) == 0:
            trailing_dot = '.'
            del labels[-1]
        else:
            trailing_dot = ''

        result = []
        for label in labels:
            result.append(ToUnicode(label))

        return ".".join(result)+trailing_dot, len(input)

class IncrementalEncoder(codecs.BufferedIncrementalEncoder):
    def _buffer_encode(self, input, errors, final):
        if errors != 'strict':
            # IDNA is quite clear that implementations must be strict
            raise UnicodeError("unsupported error handling "+errors)

        if not input:
            return (b'', 0)

        labels = dots.split(input)
        trailing_dot = b''
        if labels:
            if not labels[-1]:
                trailing_dot = b'.'
                del labels[-1]
            elif not final:
                # Keep potentially unfinished label until the next call
                del labels[-1]
                if labels:
                    trailing_dot = b'.'

        result = bytearray()
        size = 0
        for label in labels:
            if size:
                # Join with U+002E
                result.extend(b'.')
                size += 1
            result.extend(ToASCII(label))
            size += len(label)

        result += trailing_dot
        size += len(trailing_dot)
        return (bytes(result), size)

class IncrementalDecoder(codecs.BufferedIncrementalDecoder):
    def _buffer_decode(self, input, errors, final):
        if errors != 'strict':
            raise UnicodeError("Unsupported error handling "+errors)

        if not input:
            return ("", 0)

        # IDNA allows decoding to operate on Unicode strings, too.
        if isinstance(input, str):
            labels = dots.split(input)
        else:
            # Must be ASCII string
            input = str(input, "ascii")
            labels = input.split(".")

        trailing_dot = ''
        if labels:
            if not labels[-1]:
                trailing_dot = '.'
                del labels[-1]
            elif not final:
                # Keep potentially unfinished label until the next call
                del labels[-1]
                if labels:
                    trailing_dot = '.'

        result = []
        size = 0
        for label in labels:
            result.append(ToUnicode(label))
            if size:
                size += 1
            size += len(label)

        result = ".".join(result) + trailing_dot
        size += len(trailing_dot)
        return (result, size)

class StreamWriter(Codec,codecs.StreamWriter):
    pass

class StreamReader(Codec,codecs.StreamReader):
    pass

def getregentry():
    return codecs.CodecInfo(
        name='idna',
        encode=Codec().encode,
        decode=Codec().decode,
        incrementalencoder=IncrementalEncoder,
        incrementaldecoder=IncrementalDecoder,
        streamwriter=StreamWriter,
        streamreader=StreamReader,
    )

def count_history(self, request, *args, **kwargs):
        """
        To get a historical data of events amount - run **GET** against */api/events/count/history/*.
        Endpoint support same filters as events list.
        More about historical data - read at section *Historical data*.

        Response example:

        .. code-block:: javascript

            [
                {
                    "point": 141111111111,
                    "object": {
                        "count": 558
                    }
                }
            ]
        """
        queryset = self.filter_queryset(self.get_queryset())

        mapped = {
            'start': request.query_params.get('start'),
            'end': request.query_params.get('end'),
            'points_count': request.query_params.get('points_count'),
            'point_list': request.query_params.getlist('point'),
        }
        serializer = core_serializers.HistorySerializer(data={k: v for k, v in mapped.items() if v})
        serializer.is_valid(raise_exception=True)

        timestamp_ranges = [{'end': point_date} for point_date in serializer.get_filter_data()]
        aggregated_count = queryset.aggregated_count(timestamp_ranges)

        return response.Response(
            [{'point': int(ac['end']), 'object': {'count': ac['count']}} for ac in aggregated_count],
            status=status.HTTP_200_OK)

function generateISO_639_2() {
  return fs.ensureDirAsync(OUTPUT_DIR)
    .then(logger('Ensured output directory exists.'))
    .then(() => scrapeUtil.scrapePages(configs))
    .then(({ wiki, loc }) => {
      // add wiki links
      const iso_639_2 = _.mapValues(loc.iso_639_2, (value, key) => {
        const wikiValue = wiki.iso_639_2[key];

        value.wikiUrl = wikiValue.wikiUrl;

        return value;
      });

      // add biblio keys
      _.each(iso_639_2, (value, key) => {
        const bibliographic = value['639-2/B'];
        if (bibliographic) {
          iso_639_2[bibliographic] = value;
        }
      });

      delete iso_639_2['qaa-qtz'];

      // analytics
      const values = _.values(iso_639_2);
      const bib = _.chain(iso_639_2).pickBy((v, k) => v['639-2/B'] === k).values().value().length;
      const ter = _.chain(iso_639_2).pickBy((v, k) => v['639-2'] === k).values().value().length;
      console.log(`${ter} languages + ${bib} bibliographic = ${values.length} entries`);

      return iso_639_2;
    })
    .then(scrapeUtil.renderFiles(FORMATS, FILE_PREFIX, OUTPUT_DIR))
    .then(logger('Rendered output files.'))
    .catch(err => console.error(err));
}

function compileTokens(tokens) {
    var subRenders = {};

    function subRender(i, tokens, template) {
      if (!subRenders[i]) {
        var fn = compileTokens(tokens);
        subRenders[i] = function (writer, context) {
          return fn(writer, context, template);
        };
      }

      return subRenders[i];
    }

    return function (writer, context, template) {
      var buffer = "";
      var token, sectionText;

      for (var i = 0, len = tokens.length; i < len; ++i) {
        token = tokens[i];

        switch (token[0]) {
        case "#":
          sectionText = template.slice.apply(template, sectionBounds(token));
          buffer += writer._section(token[1], context, sectionText, subRender(i, token[4], template));
          break;
        case "^":
          buffer += writer._inverted(token[1], context, subRender(i, token[4], template));
          break;
        case ">":
          buffer += writer._partial(token[1], context);
          break;
        case "&":
          buffer += writer._name(token[1], context);
          break;
        case "name":
          buffer += writer._escaped(token[1], context);
          break;
        case "text":
          buffer += token[1];
          break;
        }
      }

      return buffer;
    };
  }

function InitDB(db_name) {

    var sequelize = new Sequelize(db_name, config.db.username, config.db.password, {
        host: config.db.host
        ,dialect: config.db.type
        ,logging: config.db.logging ? function(msg) {
            fs.appendFileSync("db.log", msg.replace("Executing (default): ", "") + "\n\n");
            //logger.debug(msg);
        } : false
        ,pool: {
            idle: 20000
        }
        ,define: {
            createdAt: 'created_at'
            ,updatedAt: 'updated_at'
        }
    });

    var db = {};
    fs.readdirSync("./src/db").forEach(function(file) {
        var model = sequelize.import("../src/db/" + file);
        db[model.name] = model;
    });

    Object.keys(db).reduce(function(acc, modelName) {
        var model = db[modelName];
        if("associate" in model) {
            return acc.concat([model]);
        }
        return acc;
    }, []).forEach(function(model) {
        model.associate.apply(model, [db]);
    });

    return [sequelize, db];
}

function RequireEach(options) {

    var files;
    var modules = {};
    // enables passing only path.
    if(typeof(options) === 'string')
    {
        var dir = options;
        options = {
            dirname: dir,
            filter: /(.+)\.js$/i
        };
    }else {
        options = options || {};
    }

    if (typeof(options.required) == 'undefined')
        options.required = false;

    // default filter option.
    if (!options.filter)
        options.filter = /(.*)/;

    // reset counter.
    if (typeof options._depth === 'undefined')
        options._depth = 0;

    // flatten by default
    if (typeof options.flatten === 'undefined')
        options.flatten = true;

    // Bail out if our counter has reached the desired depth
    // indicated by the user in options.depth
    if (typeof options.depth !== 'undefined' &&
        options._depth >= options.depth)
        return;

    // store starting dir
    if (!options.startDir)
        options.startDir = options.dirname;
    try {
        files = fs.readdirSync(options.dirname);
    } catch (e) {
        if (!options.required)
            return {};
        throw new Error('Directory not found: ' + options.dirname);
    }

    files.forEach(function(file) {

        var filepath = options.dirname + '/' + file;
        // iterate dirs recursively.

        if (fs.statSync(filepath).isDirectory()) {

            // ignore excluded dirs.
            if (excludeDirectory(file)) return;
            // call require on each dir.

            modules[file] = RequireEach({
                dirname: filepath,
                filter: options.filter,
                pathFilter: options.pathFilter,
                excluded: options.excluded,
                startDir: options.startDir,
                memory: options.memory,
                mark: options.mark,
                flatten: options.flatten,
                keepPath: options.keepPath,
                required: options.required,
                // track depth of iteration.
                _depth: options._depth+1,
                depth: options.depth
            });

            if (options.mark || options.flatten) {
                modules[file].isDirectory = true;
            }

            if (options.flatten) {

                modules = (function flatten(modules, accum, path) {
                    accum = accum || {};
                    Object.keys(modules).forEach(function(identity) {
                        if (typeof(modules[identity]) !== 'object' && typeof(modules[identity]) !== 'function') {
                            return;
                        }
                        if (modules[identity].isDirectory) {
                            flatten(modules[identity], accum, path ? path + '/' + identity : identity );
                        } else {
                            accum[options.keepPath ? (path ? path + '/' + identity : identity) : identity] = modules[identity];
                        }
                    });
                    return accum;
                })(modules);
            }

        }
        // process file.
        else {

            // module key
            var identity;

            // filename filter
            if (options.filter) {
                var match = file.match(options.filter);
                if (!match) return;
                identity = match[1];
            }

            // relative path filter
            if (options.pathFilter) {
                // remove relative path
                var path = filepath.replace(options.startDir, '');
                // make sure path starts with leading slash.
                path = '/' + ltrim(path, '/');
                var pathMatch = path.match(options.pathFilter);
                if (!pathMatch) return;
                identity = pathMatch[2];
            }

            // check if should load into memory/cache.
            if (options.memory) {
                modules[identity] = true;
            } else {
                if (options.required) {
                    var resolved = require.resolve(filepath);
                    if (require.cache[resolved]) delete require.cache[resolved];
                }
                modules[identity] = require(filepath);
            }

        }

    });

    return modules;

    /**
     * Helper to exclude directory by name.
     * @private
     * @param {string} dirname - the name to exclude.
     * @returns {boolean}
     */
    function excludeDirectory(dirname) {
        return options.excluded && dirname.match(options.excluded);
    }
}

function getReporter(out, style) {

	var repAccent = style.accent('/');
	var repProto = style.accent('://');

	// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -

	function tweakURI(str) {
		return str.split(/:\/\//).map(function (str) {
			return str.replace(/\//g, repAccent);
		}).join(repProto);
	}

	function tweakMessage(str) {
		return style.warning(str.charAt(0).toLowerCase() + str.substr(1));
	}

	function tweakPath(str) {
		return str.replace(/\//g, style.accent('/'));
	}

	// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -

	// best-effort
	function extractSchemaLabel(schema, limit) {
		limit = typeof limit === 'undefined' ? strimLimit : limit;
		var label = '';
		if (schema.id) {
			label = style.accent(schema.id);
		}
		if (schema.title) {
			label += style.accent(label ? ' (' + schema.title + ')' : style.accent(schema.title));
		}

		if (!label) {
			if (schema.description) {
				label = style.accent('<no id>') + ' ' + valueStrim(schema.description, limit);
			}
			else {
				label = style.accent('<no id>') + ' ' + valueStrim(schema, limit);
			}
		}
		return label;
	}

	// best-effort
	function extractCTXLabel(test, limit) {
		limit = typeof limit === 'undefined' ? strimLimit : limit;
		var label;
		if (test.label) {
			label = style.accent(test.label);
		}
		if (!label) {
			label = style.accent('<no label>') + ' ' + valueStrim(test.value, limit);
		}
		return label;
	}

	// - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - - -

	function reportResult(test, indent) {
		assertTest(test);

		if (test.result.valid) {
			if (test.failOnMissing && test.result.missing && test.result.missing.length > 0) {
				reportFailed(test, indent);
			}
			else {
				reportSuccess(test);
			}
		}
		else {
			reportFailed(test, indent);
		}
		reportMissing(test, indent);
	}

	function reportSuccess(test) {
		out.writeln(style.success('>> ') + 'success ' + extractCTXLabel(test));
		out.writeln(style.success('>> ') + extractSchemaLabel(test.schema));
	}

	function reportFailed(test, indent) {
		out.writeln(style.error('>> ') + 'failed ' + style.error(test.label));
		out.writeln(style.error('!= ') + extractSchemaLabel(test.schema));

		if (test.result.errors) {
			test.result.errors.forEach(function (err) {
				reportError(test, err, indent, indent);
			});
		}
		else if (test.result.error) {
			reportError(test, test.result.error, indent, indent);
		}
	}

	function reportMissing(test, indent) {
		if (test.result.missing && test.result.missing.length > 0) {
			out.writeln('   ' + style.warning('missing ' + pluralise('schema', test.result.missing.length) + ':') + ' ');
			test.result.missing.forEach(function (missing) {
				out.writeln(indent + style.error(' - ') + valueStrim(missing));
			});
		}
	}

	function reportError(test, error, indent, prefix, parentPath) {
		assertTest(test);

		var value = test.value;
		if (typeof test.value === 'object') {
			value = jsonpointer.get(test.value, error.dataPath);
		}
		var schemaValue = jsonpointer.get(test.schema, error.schemaPath);

		indent = (typeof indent !== 'undefined' ? String(indent) : '   ');
		prefix = (typeof prefix !== 'undefined' ? prefix : '');

		if (error.message) {
			out.writeln(prefix + tweakMessage(error.message));
		}
		else {
			out.writeln(prefix + style.error('<no message>'));
		}

		if (typeof schemaValue !== 'undefined') {
			out.writeln(prefix + indent + valueStrim(schemaValue) + style.accent(' -> ') + tweakPath(error.schemaPath));
		}
		else {
			out.writeln(prefix + indent + tweakPath(error.schemaPath));
		}

		if ((typeof parentPath !== 'string' || parentPath !== error.dataPath)) {
			if (error.dataPath !== '') {
				out.writeln(prefix + indent + style.error(' > ') + tweakPath(error.dataPath));
			}
			else {
				//out.writeln(prefix + indent + out.error(' > ') + '<root>');
			}
			if (typeof value === 'undefined') {
				out.writeln(prefix + indent + style.error(' > ') + valueType(value));
			}
			else {
				out.writeln(prefix + indent + style.error(' > ') + valueType(value) + style.error(' -> ') + valueStrim(value));
			}
		}

		if (error.subErrors) {
			error.subErrors.forEach(function (sub) {
				// let's go deeper
				reportError(test, sub, indent, prefix + indent, error.dataPath);
			});
		}
	}

	function reportTotals(numFailed, numPassed) {
		var total = numFailed + numPassed;
		if (numFailed > 0) {
			out.writeln(style.error('>> ') + 'tv4 ' + (numPassed > 0 ? style.warning('validated ' + numPassed) + ', ' : '') + style.error('failed ' + numFailed) + ' of ' + style.error(total + ' ' + pluralise('value', total)));
		}
		else if (total === 0) {
			//out.writeln('');
			out.writeln(style.warning('>> ') + 'tv4 ' + style.warning('validated zero values'));
		}
		else {
			//out.writeln('');
			out.writeln(style.success('>> ') + 'tv4 ' + style.success('validated ' + numPassed) + ' of ' + style.success(total + ' ' + pluralise('value', total)));
		}
	}

	function reportBulk(failed, passed, indent) {
		if (!passed) {
			passed = [];
		}
		indent = (typeof indent !== 'undefined' ? String(indent) : '   ');

		var total = failed.length + passed.length;

		//got some failures: print log and fail the task
		if (failed.length > 0) {
			failed.forEach(function (test, i) {
				assertTest(test);

				reportFailed(test, indent);

				if (i < failed.length - 1) {
					out.writeln('');
				}
			});
			out.writeln('');
		}
		reportTotals(failed.length, passed.length);
	}

	return {
		createTest: createTest,
		checkTest: checkTest,
		isTest: isTest,
		assertTest: assertTest,

		extractSchemaLabel: extractSchemaLabel,
		extractCTXLabel: extractCTXLabel,

		reportResult: reportResult,
		reportSuccess: reportSuccess,
		reportFailed: reportFailed,
		reportError: reportError,
		reportMissing: reportMissing,
		reportBulk: reportBulk
	};
}

def _build_request(self, method, url, params=None):
        """Build a function to do an API request

        "We have to go deeper" or "It's functions all the way down!"
        """
        full_params = self._get_base_params()
        if params is not None:
            full_params.update(params)
        try:
            request_func = lambda u, d: \
                getattr(self._connector, method.lower())(u, params=d,
                    headers=self._request_headers)
        except AttributeError:
            raise ApiException('Invalid request method')
        # TODO: need to catch a network here and raise as ApiNetworkException

        def do_request():
            logger.debug('Sending %s request "%s" with params: %r',
                method, url, full_params)
            try:
                resp = request_func(url, full_params)
                logger.debug('Received response code: %d', resp.status_code)
            except requests.RequestException as err:
                raise ApiNetworkException(err)

            try:
                resp_json = resp.json()
            except TypeError:
                resp_json = resp.json

            method_returns_list = False
            try:
                resp_json['error']
            except TypeError:
                logger.warn('Api method did not return map: %s', method)
                method_returns_list = True
            except KeyError:
                logger.warn('Api method did not return map with error key: %s', method)

            if method_returns_list is None:
                raise ApiBadResponseException(resp.content)
            elif method_returns_list:
                data = resp_json
            else:
                try:
                    if resp_json['error']:
                        raise ApiError('%s: %s' % (resp_json['code'], resp_json['message']))
                except KeyError:
                    data = resp_json
                else:
                    data = resp_json['data']
                    self._do_post_request_tasks(data)
            self._last_response = resp
            return data
        return do_request

def section(rows, columns, items, label=None):
    """A section consisting of rows and columns"""

    # TODO: Integrate label

    sections = []

    column_class = "section-column col-sm-%i" % (12 / columns)

    for vertical in range(columns):
        column_items = []
        for horizontal in range(rows):
            try:
                item = items[horizontal][vertical]
                column_items.append(item)
            except IndexError:
                hfoslog('Field in', label, 'omitted, due to missing row/column:', vertical, horizontal,
                        lvl=warn, emitter='FORMS', tb=True, frame=2)

        column = {
            'type': 'section',
            'htmlClass': column_class,
            'items': column_items
        }
        sections.append(column)

    result = {
        'type': 'section',
        'htmlClass': 'row',
        'items': sections
    }

    return result

class RunTests(Command):
    description = """Run test suite"""
    user_options = [("root=", "r", "path to tests suite dir"),
                    ("pattern=", "p", "test file name pattern"),
                    ("verbosity=", "v", "verbosity level [1,2,3]"),
                    ("files=", None,
                     "run specified test files (comma separated)"),
                    ("except-import-errors", None,
                        "except import errors when trying to import test "
                        "modules. Note: might shadow import errors raised "
                        "by the actual modules being tested")]

    def initialize_options(self):
        self.root = os.path.join(os.getcwd(), 'tests')
        self.pattern = "test*.py"
        self.verbosity = 1
        self.files = None
        self.except_import_errors = False

    def finalize_options(self):
        if not os.path.exists(self.root):
            raise IOError("Failed to access root path '{}'".format(self.root))
        verbosity = min(int(self.verbosity), 3)
        if verbosity < 1:
            self.verbosity = 1
        else:
            self.verbosity = verbosity
        if self.files:
            self.files = map(lambda name: name.strip(), self.files.split(','))
        self.except_import_errors = bool(self.except_import_errors)

    def get_modules_from_files(self, files):
        modules = []
        for file_name in files:
            directory = dirname(file_name)
            module_name, _, extension = basename(file_name).rpartition('.')
            if not module_name:
                self.announce(
                    "failed to find module name from filename '{}'." +
                    "skipping this file".format(file_name))
                continue
            package_name = self._import_dir_as_package(directory)
            if package_name:
                module_name = '.' + module_name
            elif directory not in sys.path:
                sys.path.insert(0, directory)
            self.announce(
                "importing module '{}' from file '{}' ...".format(module_name,
                                                                  file_name))
            module = import_module(module_name, package=package_name)
            modules.append(module)
        return modules

    def _import_dir_as_package(self, directory):
        """Tries to import the specified directory path as a package, if it
        seems to be a package. Returns the package name (if import was
        successful) or None if directory is not a valid package."""

        directory_name = basename(directory)
        abs_dir = abspath(directory)
        package_name = None
        if directory_name and find_source_filename('__init__', abs_dir) is not None:
            parent_dir = dirname(abs_dir)
            if parent_dir not in sys.path:
                sys.path.insert(0, parent_dir)
            try:
                self.announce(
                    "importing '{}' as package ...".format(directory_name))
                import_module(directory_name)
                package_name = directory_name
            except ImportError as err:
                self.announce(
                    "failed to import '{}'. {}".format(directory_name, err))
                if self.except_import_errors and directory_name in str(err):
                    package_name = None
                else:
                    raise err
        return package_name

    def find_test_modules_from_package_path(self, package_path):
        """Import and return modules from package __all__,
        if path is found to be a package.
        """
        package_dir = dirname(package_path)
        package_name = basename(package_path)
        if package_dir:
            sys.path.insert(0, package_dir)
        self.announce(
            "importing package '{}' ...".format(package_name)
        )
        package = import_module(package_name)
        if package and hasattr(package, '__all__'):
            modules = []
            for module_name in package.__all__:
                module = import_module('{}.{}'.format(
                    package_name, module_name))
                if type(module) == ModuleType \
                        and module not in modules:
                    modules.append(module)
            return modules

    def find_test_modules_from_test_files(self, root, pattern):
        """Return list of test modules from the the files in the path
        whose name match the pattern
        """
        modules = []
        abs_root = abspath(root)
        for (dir_path, directories, file_names) in os.walk(abs_root):
            package_name = self._import_dir_as_package(dir_path)
